import type { BodyStyle, Drivetrain, FuelType } from "../../lib/generated/prisma/enums";

export type Tag = "lux" | "perf" | "tow" | "offroad" | "family" | "work" | "threeRow" | "compact";

export type CatalogEntry = {
  make: string;
  model: string;
  body: BodyStyle;
  fuel: FuelType;
  /** [trim, approximate MSRP for the newest model year] */
  trims: [string, number][];
  /** first and last model year to generate */
  years: [number, number];
  drive: Drivetrain[];
  engine: string;
  trans: string;
  /** EPA-style city / highway MPG (omit for EVs and heavy-duty trucks) */
  mpg?: [number, number];
  /** electric range (mi) and battery (kWh) for EVs and plug-in hybrids; dc = 10–80% minutes */
  ev?: { range: number; kwh: number; dc?: number };
  wmi?: string;
  tags?: Tag[];
  manual?: boolean;
};

const E = (e: CatalogEntry) => e;

